using Assets._Project.Develop.Runtime.Gameplay.EntitiesCore;using Assets._Project.Develop.Runtime.Gameplay.EntitiesCore.Mono;using Assets._Project.Develop.Runtime.Utilities.Reactive;using System;using UnityEngine;namespace Assets._Project.Develop.Runtime.Gameplay.Features.MovementFeature{    [RequireComponent(typeof(Animator))]    public class WalkingView : EntityView    {        private readonly int IsMovingKey = Animator.StringToHash("IsWalking");        [SerializeField] private Animator _animator;        private IReadOnlyVariable<bool> _isMoving;        private bool _hasIsCurrentlyIdle;        private IReadOnlyVariable<bool> _isCurrentlyIdle;        private IDisposable _isMovingChangedDisposable;        private void OnValidate()        {            _animator ??= GetComponent<Animator>();        }        protected override void OnEntityStartedWork(Entity entity)        {            _isMoving = entity.IsMoving;            _isMovingChangedDisposable = _isMoving.Subscribe(OnIsMovingChanged);            UpdateWalkAnimator();        }        public override void Cleanup(Entity entity)        {            base.Cleanup(entity);            _isMovingChangedDisposable?.Dispose();        }        private void OnIsMovingChanged(bool oldIsMoving, bool isMoving) => UpdateWalkAnimator();        private void UpdateWalkAnimator()        {            _animator.SetBool(IsMovingKey, _isMoving.Value);        }    }}